  output [31:0] io_slave_m_WDATA,
  output [3:0]  io_slave_m_WSTRB,
  output        io_slave_m_WVALID,
  input         io_slave_m_WREADY,
                io_slave_m_BVALID,
  output        io_slave_m_BREADY,
  output [31:0] io_slave_m_ARADDR,
  output        io_slave_m_ARVALID,
  input         io_slave_m_ARREADY,
  input  [31:0] io_slave_m_RDATA,
  input         io_slave_m_RVALID,
  output        io_slave_m_RREADY,
  output [31:0] io_slave_i_ARADDR,
  output        io_slave_i_ARVALID,
  input         io_slave_i_ARREADY,
  input  [31:0] io_slave_i_RDATA,
  input         io_slave_i_RVALID,
  output        io_slave_i_RREADY,
  input         io_is_inst
);

  wire [31:0] addr = io_slave_in_ARVALID ? io_slave_in_ARADDR : io_slave_in_AWADDR;
  wire        _GEN = io_is_inst | addr == 32'hA00003F8 | addr == 32'hA0000200;
  wire        _RRESP_T_2 = addr != 32'hA00003F8;
  wire        _RRESP_T_3 = addr != 32'hA0000200;
  wire        _GEN_0 = addr == 32'hA00003F8 | addr == 32'hA0000200;
  wire        _GEN_1 = io_is_inst | _GEN_0;
  assign io_slave_in_AWREADY = ~_GEN_1 & _RRESP_T_2 & _RRESP_T_3 & io_slave_m_AWREADY;
  assign io_slave_in_WREADY = ~_GEN_1 & _RRESP_T_2 & _RRESP_T_3 & io_slave_m_WREADY;
  assign io_slave_in_BVALID = ~_GEN_1 & _RRESP_T_2 & _RRESP_T_3 & io_slave_m_BVALID;
  assign io_slave_in_ARREADY =
    io_is_inst
      ? io_slave_i_ARREADY
      : ~_GEN_0 & _RRESP_T_2 & _RRESP_T_3 & io_slave_m_ARREADY;
  assign io_slave_in_RDATA =
    io_is_inst
      ? io_slave_i_RDATA
      : _GEN_0 | ~(_RRESP_T_2 & _RRESP_T_3) ? 32'h0 : io_slave_m_RDATA;
  assign io_slave_in_RVALID =
    io_is_inst
      ? io_slave_i_RVALID
      : ~_GEN_0 & _RRESP_T_2 & _RRESP_T_3 & io_slave_m_RVALID;
  assign io_slave_m_AWADDR = _GEN ? 32'h0 : io_slave_in_AWADDR;
  assign io_slave_m_AWVALID = ~_GEN & io_slave_in_AWVALID;
  assign io_slave_m_WDATA = _GEN ? 32'h0 : io_slave_in_WDATA;
  assign io_slave_m_WSTRB = _GEN ? 4'h0 : io_slave_in_WSTRB;
  assign io_slave_m_WVALID = ~_GEN & io_slave_in_WVALID;
  assign io_slave_m_BREADY = ~_GEN & io_slave_in_BREADY;
  assign io_slave_m_ARADDR = _GEN ? 32'h0 : io_slave_in_ARADDR;
  assign io_slave_m_ARVALID = ~_GEN & io_slave_in_ARVALID;
  assign io_slave_m_RREADY = ~_GEN & io_slave_in_RREADY;
  assign io_slave_i_ARADDR = io_is_inst ? io_slave_in_ARADDR : 32'h0;
  assign io_slave_i_ARVALID = io_is_inst & io_slave_in_ARVALID;
  assign io_slave_i_RREADY = io_is_inst & io_slave_in_RREADY;
endmodule

module CSR(
  input         clock,
                reset,
  input  [11:0] io_csr_raddr,
  output [31:0] io_csr_rdata,
  input  [11:0] io_csr_waddr,
  input  [31:0] io_csr_wdata,
  input         io_csr_wen,
                io_is_ecall,
                io_is_mret
);

  reg  [31:0] mtvec;
  reg  [31:0] mepc;
  reg  [31:0] mcause;
  reg  [31:0] mstatus;
  wire        _GEN = io_csr_waddr == 12'h305;
  wire        _GEN_0 = io_csr_waddr == 12'h341;
  wire        _GEN_1 = io_csr_waddr == 12'h342;
  always @(posedge clock) begin
    if (reset) begin
      mtvec <= 32'h0;
      mepc <= 32'h0;
      mcause <= 32'h0;
      mstatus <= 32'h0;
    end
    else begin
      if (io_csr_wen & _GEN)
        mtvec <= io_csr_wdata;
      if (~io_csr_wen | _GEN | ~_GEN_0) begin
      end
      else
        mepc <= io_csr_wdata;
      if (~io_csr_wen | _GEN | _GEN_0 | ~_GEN_1) begin
        if (io_is_ecall)
          mcause <= 32'hB;
      end
      else
        mcause <= io_csr_wdata;
      if (~io_csr_wen | _GEN | _GEN_0 | _GEN_1 | io_csr_waddr != 12'h300) begin
        if (io_is_mret)
          mstatus <= {mstatus[31:8], 1'h1, mstatus[6:4], mstatus[7], mstatus[2:0]};
      end
      else
        mstatus <= io_csr_wdata;
    end
  end // always @(posedge)
  assign io_csr_rdata =
    io_csr_raddr == 12'h300
      ? mstatus
      : io_csr_raddr == 12'h342
          ? mcause
          : io_csr_raddr == 12'h341 ? mepc : io_csr_raddr == 12'h305 ? mtvec : 32'h0;
endmodule

