// ----- 8< ----- FILE "./Mem.v" ----- 8< -----

module MemBlackBox(
    input         clk,
    input         valid,
    input         wen,
    input  [31:0] raddr,
    input  [31:0] waddr,
    input  [31:0] wdata,
    input  [3:0]  wmask,
    output reg [31:0] rdata
);

import "DPI-C" function int pmem_read(input int raddr);
import "DPI-C" function void pmem_write(
  input int waddr, input int wdata, input int wmask);

// 改为256kb 的寄存器，先跑仿真

reg [31:0] mem_array [0:65535]; // 256KB

always @(*) begin
  if (valid && !wen) begin    
    //$display("PMEM_read from addr: %h, clk: %h, valid: %h, wen: %h", raddr, clk, valid, wen);
    rdata = pmem_read(raddr);    
    //rdata = mem_array[raddr]; // 256KB
  end else begin
    rdata = 32'b0;
  end
end

always @(posedge clk) begin
  if (valid && wen) begin
    pmem_write(waddr, wdata, {28'b0, wmask});
    //$display("PMEM_write to addr: %h, clk: %h, valid: %h, wen: %h", waddr, clk, valid, wen);
    //mem_array[waddr] <= wdata; // 256KB
  end
end

endmodule
// ----- 8< ----- FILE "./Inst_fetch.v" ----- 8< -----

module ImemBlackBox(
    input         clock,
    input         reset,

    input         pc_valid,
    input  [31:0] pc,

    output reg        inst_valid,
    output reg [31:0] inst
);

import "DPI-C" function int pmem_read_inst(input int pc);

reg [31:0] pc_r;
reg        pc_valid_r;

always @(posedge clock) begin
  if (reset) begin
    pc_r       <= 32'b0;
    pc_valid_r <= 1'b0;
    inst       <= 32'b0;
    inst_valid <= 1'b0;
  end else begin
    // 第 N 拍：锁存取指请求
    pc_r       <= pc;
    pc_valid_r <= pc_valid;

    // 第 N+1 拍：返回指令
    if (pc_valid_r) begin
      inst       <= pmem_read_inst(pc_r);
      inst_valid <= 1'b1;
    end else begin
      inst_valid <= 1'b0;
    end
  end
end

endmodule
// ----- 8< ----- FILE "./EbreakBlackBox.v" ----- 8< -----

module EbreakBlackBox(
    input is_ebreak
);
    import "DPI-C" function void ebreak();
    
    always @(posedge is_ebreak) begin
        if (is_ebreak) begin
            ebreak();
        end
    end
endmodule
        
